// Package firewall filters what reaches the NAS and what leaves the
// networks it hosts: its own nftables table "inet titanos", generated by
// titand from /config/firewall/settings.json.
//
// Off (the default) the table holds at most the addresses the automatic
// blocking has locked out; everything else stays as open as the image makes
// it (titanos-firewall-open). On, every packet that is not part of a known
// connection is put into a zone by where it comes from: the built-in zones
// home network, VPN, internet and Docker, or own zones made of networks of
// the NAS (VLANs, bridges, Docker networks) and source networks. A matrix of
// cells source zone × destination (the NAS itself, published ports of
// Docker apps, other zones for traffic the NAS forwards) holds ordered
// policies, first match wins, and a default for each cell.
//
// A switched-on or changed rule set is on trial like a network change:
// unless the web UI confirms it within two minutes, the previous rules come
// back.
package firewall

import (
	"errors"
	"fmt"
	"net/netip"
	"regexp"
	"slices"
	"strconv"
	"strings"
)

const (
	settingsFile = "firewall/settings.json"
	// blockedFile keeps the permanent blocks; temporary ones live in RAM
	// (and in /run across a restart of titand).
	blockedFile = "firewall/blocked.json"
	// maxPolicies per cell: room for an app policy of every app (512) and
	// as many own policies as the old own rules (100).
	maxPolicies    = 640
	maxCustomZones = 16
	maxZoneEntries = 64
	maxExempt      = 64
	maxComment     = 80
	maxZoneName    = 40
)

var (
	ErrDisabled  = errors.New("firewall: not available in development mode")
	ErrNotLoaded = errors.New("firewall: settings could not be read from /config")
	// ErrInvalid means a setting is not acceptable; the message says which.
	ErrInvalid   = errors.New("firewall: invalid setting")
	ErrPending   = errors.New("firewall: a change is waiting for confirmation")
	ErrNoPending = errors.New("firewall: no change is waiting for confirmation")
	// ErrExcludesYou means the rules would keep the admin who saves them
	// out of the web UI.
	ErrExcludesYou = errors.New("firewall: the rules would lock you out of the web UI")
	ErrNotBlocked  = errors.New("firewall: this address is not blocked")
	// ErrUnavailable means nft is missing or refused the rules.
	ErrUnavailable = errors.New("firewall: the rules could not be loaded")
)

// Zone is the ID of a zone: a built-in one or z<letters and digits>.
type Zone string

const (
	Home     Zone = "home"
	VPN      Zone = "vpn"
	Internet Zone = "internet"
	// Docker holds every Docker bridge network that is not in an own zone.
	Docker Zone = "docker"
)

// builtinZones in the order of the page.
var builtinZones = []Zone{Home, VPN, Internet, Docker}

// legacyZones are the zones of settings version 1 (and of Zones).
var legacyZones = []Zone{Home, VPN, Internet}

// The destinations of a cell besides the zones.
const (
	// ToNAS are the services of the NAS itself (input hook).
	ToNAS = "nas"
	// ToApps are the published ports of Docker apps (forward after DNAT).
	ToApps = "apps"
)

const (
	Allow = "allow"
	Deny  = "deny"
)

var (
	customZoneRE = regexp.MustCompile(`^z[a-z0-9]{1,14}$`)
	networkIDRE  = regexp.MustCompile(`^(net|docker|vm):[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$`)
	appKeyRE     = regexp.MustCompile(`^(container:)?[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$`)
)

// ZoneDef is a zone of the matrix.
type ZoneDef struct {
	ID Zone `json:"id"`
	// Name of an own zone; the built-in ones are named by the web UI.
	Name    string `json:"name,omitempty"`
	Builtin bool   `json:"builtin,omitempty"`
	// Networks are the IDs of networks of the NAS in this own zone
	// (net:<logical network>, docker:<Docker network>, vm:<bridge>). Docker
	// networks not listed in an own zone are in the zone Docker; other
	// networks not listed are put in a zone by their addresses.
	Networks []string `json:"networks"`
	// Sources are addresses and networks that belong to this own zone,
	// wherever they come from.
	Sources []string `json:"sources"`
}

// Policy is one line of a cell, checked in order; the first that matches
// decides.
type Policy struct {
	// Action is allow or deny.
	Action string `json:"action"`
	// Protocol is tcp, udp or any; ignored for Service and App.
	Protocol string `json:"protocol"`
	// Ports is empty (all), a port (22) or a range (8000-8100).
	Ports string `json:"ports,omitempty"`
	// Service is a service of the NAS (cells to the NAS only).
	Service string `json:"service,omitempty"`
	// App is a Docker app (cells to the apps only).
	App string `json:"app,omitempty"`
	// Source is empty (anyone in the zone), an address or a network.
	Source string `json:"source,omitempty"`
	// Destination is an address or network (cells to a zone only).
	Destination string `json:"destination,omitempty"`
	Comment     string `json:"comment,omitempty"`
	Disabled    bool   `json:"disabled,omitempty"`
}

// Cell is what one zone may reach of one destination.
type Cell struct {
	From Zone `json:"from"`
	// To is nas, apps or the ID of a zone.
	To       string   `json:"to"`
	Policies []Policy `json:"policies"`
	// Default is allow or deny, for what no policy matches.
	Default string `json:"default"`
}

// AutoBlock locks out senders after failed logins, like Synology's
// "Auto Block". Off by default.
type AutoBlock struct {
	Enabled bool `json:"enabled"`
	// Attempts failed logins within Within minutes block the sender.
	Attempts int `json:"attempts"`
	Within   int `json:"within"`
	// Minutes is how long a block lasts unless Permanent.
	Minutes   int  `json:"minutes"`
	Permanent bool `json:"permanent"`
	// ExemptLocal never blocks the home network and the VPN.
	ExemptLocal bool `json:"exemptLocal"`
	// Exempt are addresses and networks that are never blocked.
	Exempt []string `json:"exempt"`
}

// Config are the settings (version 2: zones and cells). On the stick they
// are kept next to a version-1 view for older titand (see file.go).
type Config struct {
	Enabled   bool      `json:"enabled"`
	Zones     []ZoneDef `json:"zones"`
	Cells     []Cell    `json:"cells"`
	AutoBlock AutoBlock `json:"autoBlock"`
}

// Zone returns the zone with that ID.
func (cfg Config) Zone(id Zone) (ZoneDef, bool) {
	i := slices.IndexFunc(cfg.Zones, func(z ZoneDef) bool { return z.ID == id })
	if i < 0 {
		return ZoneDef{}, false
	}
	return cfg.Zones[i], true
}

// Cell returns the cell of a pair; a missing one has its default.
func (cfg Config) Cell(from Zone, to string) Cell {
	if i := slices.IndexFunc(cfg.Cells, func(c Cell) bool { return c.From == from && c.To == to }); i >= 0 {
		return cfg.Cells[i]
	}
	return defaultCell(cfg, from, to)
}

// isHosted tells whether a network ID stands for a network behind the NAS
// (Docker bridge, VM/LXC NAT bridge): its traffic to other zones passes
// the forward hook of the NAS and can be filtered there.
func isHosted(network string) bool {
	return strings.HasPrefix(network, "docker:") || strings.HasPrefix(network, "vm:")
}

// Hosted tells whether a zone holds networks behind the NAS. Only those
// zones have cells to other zones: traffic between the home network, the
// VPN and the internet does not pass the NAS (it is no router).
func (cfg Config) Hosted(id Zone) bool {
	if id == Docker {
		return true
	}
	z, ok := cfg.Zone(id)
	return ok && !z.Builtin && slices.ContainsFunc(z.Networks, isHosted)
}

// destinations of a zone in the order of the matrix.
func (cfg Config) destinations(from Zone) []string {
	out := []string{ToNAS, ToApps}
	if cfg.Hosted(from) {
		for _, z := range cfg.Zones {
			out = append(out, string(z.ID))
		}
	}
	return out
}

// Defaults: home network and VPN allowed, internet blocked; Docker
// networks reach the internet and other zones, the NAS only for DNS and the
// HTTPS names of apps, and not each other.
var (
	local    = Zones{Home: true, VPN: true}
	homeOnly = Zones{Home: true}
)

// defaultCell is a cell nobody changed.
func defaultCell(cfg Config, from Zone, to string) Cell {
	c := Cell{From: from, To: to, Policies: []Policy{}, Default: Deny}
	switch to {
	case ToNAS:
		switch from {
		case Home, VPN, Internet:
			for _, s := range Services(nil) {
				if s.Default.Has(from) {
					c.Policies = append(c.Policies, Policy{Action: Allow, Protocol: "any", Service: s.ID})
				}
			}
		case Docker:
			c.Policies = append(c.Policies,
				Policy{Action: Allow, Protocol: "any", Service: "apps"},
				Policy{Action: Allow, Protocol: "any", Ports: "53", Comment: "DNS"})
		}
	case ToApps:
		if from == Home || from == VPN || from == Docker {
			c.Default = Allow
		}
	default:
		// Out of a network behind the NAS: everywhere but into another
		// network behind the NAS (Docker isolates its networks, too).
		if !cfg.Hosted(Zone(to)) {
			c.Default = Allow
		}
	}
	return c
}

// Defaults returns the settings of a NAS that never changed them.
func Defaults() Config {
	return normal(Config{AutoBlock: AutoBlock{Attempts: 10, Within: 5, Minutes: 60, ExemptLocal: true, Exempt: []string{}}})
}

// normal fills in what an older or partial configuration leaves out: the
// built-in zones first, every cell once, tidy policies.
func normal(cfg Config) Config {
	zones := make([]ZoneDef, 0, len(cfg.Zones)+len(builtinZones))
	for _, id := range builtinZones {
		zones = append(zones, ZoneDef{ID: id, Builtin: true, Networks: []string{}, Sources: []string{}})
	}
	for _, z := range cfg.Zones {
		if slices.Contains(builtinZones, z.ID) || slices.ContainsFunc(zones, func(o ZoneDef) bool { return o.ID == z.ID }) {
			continue
		}
		z.Builtin = false
		z.Name = strings.TrimSpace(z.Name)
		z.Networks = tidyList(z.Networks)
		z.Sources = tidyList(z.Sources)
		zones = append(zones, z)
	}
	cfg.Zones = zones

	cells := make([]Cell, 0, len(zones)*(len(zones)+2))
	for _, z := range zones {
		for _, to := range cfg.destinations(z.ID) {
			cell := cfg.Cell(z.ID, to)
			cell.Default = strings.ToLower(strings.TrimSpace(cell.Default))
			policies := make([]Policy, 0, len(cell.Policies))
			for _, p := range cell.Policies {
				policies = append(policies, tidyPolicy(p))
			}
			cell.Policies = policies
			cells = append(cells, cell)
		}
	}
	cfg.Cells = cells

	if cfg.AutoBlock.Attempts == 0 && cfg.AutoBlock.Within == 0 && cfg.AutoBlock.Minutes == 0 {
		enabled := cfg.AutoBlock.Enabled
		cfg.AutoBlock = AutoBlock{Attempts: 10, Within: 5, Minutes: 60, ExemptLocal: true}
		cfg.AutoBlock.Enabled = enabled
	}
	if cfg.AutoBlock.Exempt == nil {
		cfg.AutoBlock.Exempt = []string{}
	}
	return cfg
}

func tidyList(list []string) []string {
	out := []string{}
	for _, s := range list {
		if s = strings.TrimSpace(s); s != "" && !slices.Contains(out, s) {
			out = append(out, s)
		}
	}
	return out
}

func tidyPolicy(p Policy) Policy {
	p.Action, p.Protocol = strings.ToLower(strings.TrimSpace(p.Action)), strings.ToLower(strings.TrimSpace(p.Protocol))
	p.Service, p.App = strings.TrimSpace(p.Service), strings.TrimSpace(p.App)
	p.Ports = strings.ReplaceAll(strings.TrimSpace(p.Ports), " ", "")
	p.Source, p.Destination = strings.TrimSpace(p.Source), strings.TrimSpace(p.Destination)
	p.Comment = strings.TrimSpace(p.Comment)
	if p.Protocol == "" || p.Service != "" || p.App != "" {
		p.Protocol = "any"
	}
	if p.Service != "" || p.App != "" {
		p.Ports = ""
	}
	return p
}

// validate checks a configuration that has been through normal.
func validate(cfg Config) error {
	invalid := func(format string, args ...any) error {
		return fmt.Errorf("%w: "+format, append([]any{ErrInvalid}, args...)...)
	}
	custom := 0
	owner := map[string]Zone{}
	for _, z := range cfg.Zones {
		if z.Builtin {
			if len(z.Networks) > 0 || len(z.Sources) > 0 {
				return invalid("zone %s has no networks of its own", z.ID)
			}
			continue
		}
		custom++
		if !customZoneRE.MatchString(string(z.ID)) {
			return invalid("zone ID %q", z.ID)
		}
		if n := len([]rune(z.Name)); n == 0 || n > maxZoneName || strings.ContainsAny(z.Name, "\"\\\n\r\t") {
			return invalid("name of zone %s", z.ID)
		}
		if len(z.Networks) > maxZoneEntries || len(z.Sources) > maxZoneEntries {
			return invalid("zone %s: at most %d networks and %d sources", z.ID, maxZoneEntries, maxZoneEntries)
		}
		for _, n := range z.Networks {
			if !networkIDRE.MatchString(n) {
				return invalid("zone %s: network %q", z.ID, n)
			}
			if other, ok := owner[n]; ok {
				return invalid("network %s is in zones %s and %s", n, other, z.ID)
			}
			owner[n] = z.ID
		}
		for _, s := range z.Sources {
			if _, err := parseSource(s); err != nil {
				return invalid("zone %s: source %q", z.ID, s)
			}
		}
	}
	if custom > maxCustomZones {
		return invalid("at most %d own zones", maxCustomZones)
	}
	services := Services(nil)
	for _, c := range cfg.Cells {
		if c.Default != Allow && c.Default != Deny {
			return invalid("cell %s → %s: default must be allow or deny", c.From, c.To)
		}
		if len(c.Policies) > maxPolicies {
			return invalid("cell %s → %s: at most %d policies", c.From, c.To, maxPolicies)
		}
		for i, p := range c.Policies {
			if err := validatePolicy(p, c.To, services); err != nil {
				return invalid("cell %s → %s, policy %d: %v", c.From, c.To, i+1, err)
			}
		}
	}
	return validateAutoBlock(cfg.AutoBlock)
}

func validatePolicy(p Policy, to string, services []Service) error {
	if p.Action != Allow && p.Action != Deny {
		return errors.New("action must be allow or deny")
	}
	if !slices.Contains([]string{"tcp", "udp", "any"}, p.Protocol) {
		return errors.New("protocol must be tcp, udp or any")
	}
	if p.Ports != "" {
		if _, _, err := parsePorts(p.Ports); err != nil {
			return err
		}
	}
	if p.Service != "" {
		if to != ToNAS {
			return errors.New("services only in cells to the NAS")
		}
		if _, ok := serviceByID(services, p.Service); !ok {
			return errors.New("unknown service")
		}
	}
	if p.App != "" {
		if to != ToApps {
			return errors.New("apps only in cells to the apps")
		}
		if !appKeyRE.MatchString(p.App) {
			return errors.New("app name")
		}
	}
	if p.Source != "" {
		if _, err := parseSource(p.Source); err != nil {
			return err
		}
	}
	if p.Destination != "" {
		if to == ToNAS || to == ToApps {
			return errors.New("a destination only in cells to a zone")
		}
		if _, err := parseSource(p.Destination); err != nil {
			return err
		}
	}
	if len([]rune(p.Comment)) > maxComment || strings.ContainsAny(p.Comment, "\"\\\n\r\t") {
		return errors.New("comment too long or with quotes")
	}
	return nil
}

func validateAutoBlock(a AutoBlock) error {
	switch {
	case a.Attempts < 2 || a.Attempts > 100:
		return fmt.Errorf("%w: attempts must be 2 to 100", ErrInvalid)
	case a.Within < 1 || a.Within > 1440:
		return fmt.Errorf("%w: within must be 1 to 1440 minutes", ErrInvalid)
	case !a.Permanent && (a.Minutes < 1 || a.Minutes > 525600):
		return fmt.Errorf("%w: block for 1 minute to 365 days", ErrInvalid)
	case len(a.Exempt) > maxExempt:
		return fmt.Errorf("%w: at most %d exempt networks", ErrInvalid, maxExempt)
	}
	for _, entry := range a.Exempt {
		if _, err := parseSource(entry); err != nil {
			return fmt.Errorf("%w: exempt %q", ErrInvalid, entry)
		}
	}
	return nil
}

// parsePorts reads "22" or "8000-8100".
func parsePorts(text string) (int, int, error) {
	from, to, isRange := strings.Cut(text, "-")
	low, err := strconv.Atoi(from)
	if err != nil || low < 1 || low > 65535 {
		return 0, 0, fmt.Errorf("port %q", text)
	}
	high := low
	if isRange {
		high, err = strconv.Atoi(to)
		if err != nil || high < low || high > 65535 {
			return 0, 0, fmt.Errorf("port range %q", text)
		}
	}
	return low, high, nil
}

// parseSource reads an address (as /32 or /128) or a network.
func parseSource(text string) (netip.Prefix, error) {
	if strings.Contains(text, "%") {
		return netip.Prefix{}, errors.New("zones are not allowed")
	}
	if !strings.Contains(text, "/") {
		addr, err := netip.ParseAddr(text)
		if err != nil {
			return netip.Prefix{}, err
		}
		addr = addr.Unmap()
		return netip.PrefixFrom(addr, addr.BitLen()), nil
	}
	prefix, err := netip.ParsePrefix(text)
	if err != nil {
		return netip.Prefix{}, err
	}
	if prefix.Addr().Is4In6() {
		return netip.Prefix{}, errors.New("mapped address")
	}
	return prefix.Masked(), nil
}

// clone copies a configuration so callers cannot change the manager's.
func clone(cfg Config) Config {
	out := cfg
	out.Zones = make([]ZoneDef, len(cfg.Zones))
	for i, z := range cfg.Zones {
		z.Networks = slices.Clone(z.Networks)
		z.Sources = slices.Clone(z.Sources)
		if z.Networks == nil {
			z.Networks = []string{}
		}
		if z.Sources == nil {
			z.Sources = []string{}
		}
		out.Zones[i] = z
	}
	out.Cells = make([]Cell, len(cfg.Cells))
	for i, c := range cfg.Cells {
		c.Policies = slices.Clone(c.Policies)
		if c.Policies == nil {
			c.Policies = []Policy{}
		}
		out.Cells[i] = c
	}
	out.AutoBlock.Exempt = slices.Clone(cfg.AutoBlock.Exempt)
	if out.AutoBlock.Exempt == nil {
		out.AutoBlock.Exempt = []string{}
	}
	return out
}

// setCell replaces (or adds) a cell.
func (cfg *Config) setCell(c Cell) {
	if i := slices.IndexFunc(cfg.Cells, func(o Cell) bool { return o.From == c.From && o.To == c.To }); i >= 0 {
		cfg.Cells[i] = c
		return
	}
	cfg.Cells = append(cfg.Cells, c)
}
